// Package interactive provides TTY-related helpers shared between the cli
// and strategy packages without inducing an import cycle (strategy cannot
// import cli).
package interactive

import (
	"io"
	"os"
	"testing"

	"golang.org/x/term"
)

// EnvTestTTY is the env-var name for the force-interactive test override.
//   - EnvTestTTY=1 → CanPromptInteractively returns true.
//   - EnvTestTTY set to any other value → returns false.
//   - EnvTestTTY unset → real detection via testing.Testing(), agent
//     sentinels, CI, then /dev/tty probe.
const EnvTestTTY = "ENTIRE_TEST_TTY"

// CanPromptInteractively reports whether interactive confirmation prompts
// (huh forms, yes/no questions, etc.) can be shown. Returns false in CI,
// agent subprocesses that inherit a TTY but can't respond to prompts,
// and other environments without a controlling TTY.
//
// Precedence (first match wins):
//  1. EnvTestTTY=1 forces interactive ON; any other non-empty value forces OFF.
//  2. testing.Testing() — `go test` runs default to OFF so in-process tests
//     don't hang on developer terminals that happen to have a real /dev/tty.
//     Subprocess tests must spawn via execx.NonInteractive (or set EnvTestTTY).
//  3. Agent sentinels — vendor-set by agent subprocesses.
//  4. CI=<non-empty-non-false> — de-facto CI convention.
//  5. /dev/tty probe, plus its terminal mode: a controlling terminal held in
//     raw mode belongs to a full-screen TUI (lazygit, gitui, tig, …) that
//     spawned us, not to a shell we can prompt. See rawmode_unix.go.
func CanPromptInteractively() bool {
	if v := os.Getenv(EnvTestTTY); v != "" {
		return v == "1"
	}
	if testing.Testing() {
		return false
	}
	if isAgentSubprocessEnv() {
		return false
	}
	// CI=<non-empty> is the de-facto CI-provider convention (GitHub Actions,
	// CircleCI, GitLab, Travis, Buildkite). Self-hosted runners expose /dev/tty,
	// so the probe below isn't enough — an interactive prompt on CI hangs.
	// CI=false is the `is-ci` escape hatch for developers who need to override
	// an inherited value.
	if v := os.Getenv("CI"); v != "" && v != "false" {
		return false
	}

	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return false
	}
	defer tty.Close()
	// Having a controlling terminal isn't enough — a TUI that spawned us holds
	// that same terminal in raw mode for its own screen and keys. See
	// rawmode_unix.go.
	return !ttyInRawMode(tty)
}

// UnderTest reports whether the process is running in a test context — either
// inside `go test` (testing.Testing()) or with EnvTestTTY explicitly set. Use
// to skip operations that read from the real terminal (e.g. opening /dev/tty)
// even when CanPromptInteractively() returns true.
func UnderTest() bool {
	return testing.Testing() || os.Getenv(EnvTestTTY) != ""
}

// agentSubprocessEnvVars are vendor-set variables that mark a process spawned
// by an agent's shell tool or hook runner. Presence alone is the signal —
// vendors spell the value differently ("1", "true"), so only an empty or unset
// value means absent.
//
// This is the single source of truth for the list: isAgentSubprocessEnv reads
// it, and the tests both enumerate it and clear it. Adding a name here is the
// whole change.
//
//   - CLAUDECODE is deliberately absent. Claude Code sets it to 1 in its tool
//     subprocesses, so it could join this list, but doing so withdraws every
//     interactive prompt from the largest agent population at once. That is a
//     product call, not a detection fix.
var agentSubprocessEnvVars = []string{
	"COPILOT_CLI",     // Copilot CLI hook subprocesses (v0.0.421+)
	"CURSOR_AGENT",    // cursor-agent shell tool; set alongside CURSOR_CONVERSATION_ID
	"GEMINI_CLI",      // Gemini CLI shell tool (https://geminicli.com/docs/tools/shell/)
	"OPENCODE",        // set on opencode's own process, so every child inherits it
	"PI_CODING_AGENT", // Pi Coding Agent shell tool
}

// isAgentSubprocessEnv reports whether the env indicates we're running inside
// an agent subprocess that inherited a TTY but can't respond to prompts:
// either one of agentSubprocessEnvVars is set, or GIT_TERMINAL_PROMPT=0 —
// the caller (CI, Factory AI Droid, etc.) asked git to stop prompting, and we
// respect it from git-hook context too.
//
// GIT_TERMINAL_PROMPT stays outside the list because its semantics differ: it
// is a tri-state the user may legitimately set to "1", so only the exact value
// "0" counts, where the others are presence checks.
func isAgentSubprocessEnv() bool {
	for _, name := range agentSubprocessEnvVars {
		if os.Getenv(name) != "" {
			return true
		}
	}
	return os.Getenv("GIT_TERMINAL_PROMPT") == "0"
}

// IsTerminalReader reports whether r is an *os.File backed by a terminal.
// It is useful when an explicitly interactive command needs to distinguish a
// human at stdin from an agent process that merely inherited a controlling TTY.
func IsTerminalReader(r io.Reader) bool {
	f, ok := r.(*os.File)
	if !ok {
		return false
	}
	return term.IsTerminal(int(f.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
}

// IsTerminalWriter reports whether w is an *os.File backed by a terminal.
// Use for deciding on color, pager, progress bars, or other writer-scoped
// TTY formatting. For "can I prompt the user?" use CanPromptInteractively.
func IsTerminalWriter(w io.Writer) bool {
	f, ok := w.(*os.File)
	if !ok {
		return false
	}
	return term.IsTerminal(int(f.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
}

// ShouldStyle reports whether ANSI-styled output (color, bold, rendered
// markdown) should be written to w. It is the single gate for writer-scoped
// styling decisions: NO_COLOR disables styling per https://no-color.org,
// legacy consoles that can't handle ANSI escapes are excluded, and otherwise
// the answer is whether w is a terminal.
func ShouldStyle(w io.Writer) bool {
	return shouldStyle(os.Getenv("NO_COLOR"), os.Getenv("TERM"), IsTerminalWriter(w))
}

// shouldStyle is the pure decision behind ShouldStyle, split out so tests can
// exercise the NO_COLOR/TERM gates with a simulated terminal writer — `go
// test` never has a real one, so testing through ShouldStyle would
// short-circuit on the terminal check and never reach the earlier gates.
func shouldStyle(noColor, term string, isTerminalWriter bool) bool {
	if noColor != "" {
		return false
	}
	if termLacksANSI(term) {
		return false
	}
	return isTerminalWriter
}

// termLacksANSI reports whether term identifies a legacy console that does
// not reliably handle ANSI escape sequences. The canonical case is
// TERM=cygwin: writing the ESC byte (0x1B) ends up rendered as the CP437
// glyph U+2190 LEFTWARDS ARROW ("←") instead of starting an SGR sequence, so
// styled output appears as literal text like "←[32m●←[m" (see GH #1267).
func termLacksANSI(term string) bool {
	return term == "cygwin"
}

package strategy

import (
	"context"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/proclive"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// clearCallerSessionEnv unsets every agent's caller-session variable, derived
// from the registry rather than hand-listed so it cannot rot when an agent is
// added. Necessary because `go test` is routinely run from inside one of these
// agents, whose variable would otherwise leak into every case below.
func clearCallerSessionEnv(t *testing.T) {
	t.Helper()
	for _, name := range agent.CallerSessionEnvVars() {
		t.Setenv(name, "")
	}
}

// callerSessionRepo sets up an isolated repo, chdirs into it, and returns the
// worktree root as git resolves it (symlinks and all, e.g. /var →
// /private/var on macOS) so a state's WorktreePath can be made to match.
func callerSessionRepo(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)
	resolved, err := paths.WorktreeRoot(context.Background())
	if err != nil {
		t.Fatalf("paths.WorktreeRoot() error = %v", err)
	}
	return resolved
}

func saveState(t *testing.T, id, worktree string, lastInteraction time.Time) {
	t.Helper()
	state := &SessionState{
		SessionID:           id,
		BaseCommit:          "abc1234",
		WorktreePath:        worktree,
		StartedAt:           lastInteraction,
		LastInteractionTime: &lastInteraction,
		Phase:               "idle",
	}
	if err := SaveSessionState(context.Background(), state); err != nil {
		t.Fatalf("SaveSessionState(%q) error = %v", id, err)
	}
}

// The reported bug, as a test: an agent asks which session is running it from
// a worktree that has no sessions of its own. Before the caller tier, the
// answer was another worktree's live session, indistinguishable from a real
// one — which is what got fed to `session adopt`.
func TestResolveCallerSession_PrefersTheCallerOverAnotherWorktreesSession(t *testing.T) {
	clearCallerSessionEnv(t)
	callerSessionRepo(t)

	saveState(t, "elsewhere-session", "/some/other/worktree", time.Now())
	saveState(t, "caller-session", "/a/third/worktree", time.Now().Add(-2*time.Hour))
	t.Setenv("CODEX_SESSION_ID", "caller-session")

	got := ResolveCallerSession(context.Background())
	if got.SessionID != "caller-session" {
		t.Errorf("SessionID = %q, want %q (the caller, not the most recent)", got.SessionID, "caller-session")
	}
	if got.Resolution != ResolutionCallerEnv {
		t.Errorf("Resolution = %q, want %q", got.Resolution, ResolutionCallerEnv)
	}
	if !got.Tracked {
		t.Error("Tracked = false; state was saved for this session")
	}
	if !got.Resolution.IsCaller() {
		t.Error("IsCaller() = false for the caller-env tier")
	}
}

func TestResolveCallerSession_FallsBackToThisWorktree(t *testing.T) {
	clearCallerSessionEnv(t)
	worktree := callerSessionRepo(t)

	saveState(t, "elsewhere-session", "/some/other/worktree", time.Now())
	saveState(t, "local-session", worktree, time.Now().Add(-time.Hour))

	got := ResolveCallerSession(context.Background())
	if got.SessionID != "local-session" {
		t.Errorf("SessionID = %q, want %q (prefer this worktree over a newer foreign one)", got.SessionID, "local-session")
	}
	if got.Resolution != ResolutionWorktree {
		t.Errorf("Resolution = %q, want %q", got.Resolution, ResolutionWorktree)
	}
	if got.Resolution.IsCaller() {
		t.Error("IsCaller() = true for the worktree tier; it is an inference, not an identification")
	}
}

// The weakest tier must still be reachable — it is what a human asking "what
// has been happening in this repo" wants — but it must announce itself, since
// nothing about it relates to the caller.
func TestResolveCallerSession_LabelsTheCrossWorktreeFallback(t *testing.T) {
	clearCallerSessionEnv(t)
	callerSessionRepo(t)

	saveState(t, "elsewhere-session", "/some/other/worktree", time.Now())

	got := ResolveCallerSession(context.Background())
	if got.SessionID != "elsewhere-session" {
		t.Errorf("SessionID = %q, want %q", got.SessionID, "elsewhere-session")
	}
	if got.Resolution != ResolutionOtherWorktree {
		t.Errorf("Resolution = %q, want %q", got.Resolution, ResolutionOtherWorktree)
	}
	if got.Resolution.IsCaller() {
		t.Error("IsCaller() = true for the other-worktree tier; this is the one an agent must never act on")
	}
}

func TestResolveCallerSession_NothingFound(t *testing.T) {
	clearCallerSessionEnv(t)
	callerSessionRepo(t)

	got := ResolveCallerSession(context.Background())
	if got.Found() {
		t.Errorf("ResolveCallerSession() = %+v, want no session", got)
	}
	if got.Resolution != ResolutionNone {
		t.Errorf("Resolution = %q, want %q", got.Resolution, ResolutionNone)
	}
}

// An agent named its session but Entire holds no state for it: hooks are not
// installed, they failed, or the first turn has not landed. The ID and the
// agent are still reported, because "you are in session X and Entire is not
// recording it" is a diagnosis — and crucially it must NOT fall through to a
// weaker tier and answer with someone else's session.
func TestResolveCallerSession_ReportsAnUntrackedCallerRatherThanGuessing(t *testing.T) {
	clearCallerSessionEnv(t)
	callerSessionRepo(t)

	saveState(t, "elsewhere-session", "/some/other/worktree", time.Now())
	t.Setenv("CURSOR_CONVERSATION_ID", "untracked-caller")

	got := ResolveCallerSession(context.Background())
	if got.SessionID != "untracked-caller" {
		t.Errorf("SessionID = %q, want %q", got.SessionID, "untracked-caller")
	}
	if got.Tracked {
		t.Error("Tracked = true; no state was saved for this session")
	}
	if got.Resolution != ResolutionCallerEnv {
		t.Errorf("Resolution = %q, want %q", got.Resolution, ResolutionCallerEnv)
	}
	if got.AgentType == "" {
		t.Error("AgentType is empty; the environment names the agent even when state is missing")
	}
}

// A tracked claim beats an untracked one. In a nested pair the untracked claim
// is often just the outer agent, and a session Entire actually holds is
// strictly more useful than an ID it knows nothing about.
func TestResolveCallerSession_TrackedClaimBeatsUntrackedClaim(t *testing.T) {
	clearCallerSessionEnv(t)
	callerSessionRepo(t)

	saveState(t, "inner-session", "/some/other/worktree", time.Now())
	t.Setenv("CLAUDE_CODE_SESSION_ID", "outer-untracked")
	t.Setenv("CODEX_SESSION_ID", "inner-session")

	got := ResolveCallerSession(context.Background())
	if got.SessionID != "inner-session" {
		t.Errorf("SessionID = %q, want the tracked claim %q", got.SessionID, "inner-session")
	}
	if !got.Tracked {
		t.Error("Tracked = false; the tracked candidate should have won")
	}
}

// Two tracked claims and no usable ancestry (no Owner recorded on either):
// the most recently interacting one wins, because in a nested pair the inner
// agent is the one doing the work.
func TestResolveCallerSession_NestedTrackedClaimsFallBackToRecency(t *testing.T) {
	clearCallerSessionEnv(t)
	callerSessionRepo(t)

	saveState(t, "outer-session", "/some/other/worktree", time.Now().Add(-time.Hour))
	saveState(t, "inner-session", "/some/other/worktree", time.Now())
	t.Setenv("CLAUDE_CODE_SESSION_ID", "outer-session")
	t.Setenv("CODEX_SESSION_ID", "inner-session")

	got := ResolveCallerSession(context.Background())
	if got.SessionID != "inner-session" {
		t.Errorf("SessionID = %q, want the more recently active nested claim %q", got.SessionID, "inner-session")
	}
}

// An unsafe value reads as absent at the agent layer, so the resolver must
// degrade to a weaker tier rather than carry it — never resolve a path from an
// ID the environment supplied unchecked.
func TestResolveCallerSession_IgnoresAnUnsafePublishedID(t *testing.T) {
	clearCallerSessionEnv(t)
	worktree := callerSessionRepo(t)

	saveState(t, "local-session", worktree, time.Now())
	t.Setenv("CODEX_SESSION_ID", "../../../etc/passwd")

	got := ResolveCallerSession(context.Background())
	if got.SessionID != "local-session" || got.Resolution != ResolutionWorktree {
		t.Errorf("ResolveCallerSession() = %+v, want the worktree tier", got)
	}
}

func TestSessionResolution_IsCaller(t *testing.T) {
	cases := map[SessionResolution]bool{
		ResolutionCallerEnv:     true,
		ResolutionAncestry:      true,
		ResolutionWorktree:      false,
		ResolutionOtherWorktree: false,
		ResolutionNone:          false,
	}
	for resolution, want := range cases {
		if got := resolution.IsCaller(); got != want {
			t.Errorf("SessionResolution(%q).IsCaller() = %v, want %v", resolution, got, want)
		}
	}
}

// The ancestry tier, exercised with a real identity rather than a fixture:
// proclive.Chain() is the documented way tests obtain live identities at known
// depths, so recording chain[0] as a session's owner makes that session
// genuinely our nearest-ancestor match.
//
// This tier is what covers the agents that publish no session ID — Gemini CLI
// and opencode — so it must not be left to the environment-variable tests.
func TestResolveCallerSession_MatchesOwnerByProcessAncestry(t *testing.T) {
	clearCallerSessionEnv(t)
	callerSessionRepo(t)

	ancestry, ok := proclive.CurrentAncestry()
	if !ok {
		t.Skip("platform cannot introspect processes; the ancestry tier is unavailable here by design")
	}
	chain := ancestry.Chain()
	if len(chain) == 0 {
		t.Skip("no ancestors visible; nothing to match against")
	}
	owner := chain[0]

	newer := time.Now()
	older := newer.Add(-2 * time.Hour)
	// A newer session elsewhere that ancestry must lose to, so a pass cannot
	// come from the recency tiers underneath.
	saveState(t, "newer-elsewhere", "/some/other/worktree", newer)

	owned := &SessionState{
		SessionID:           "ancestry-owned",
		BaseCommit:          "abc1234",
		WorktreePath:        "/a/third/worktree",
		StartedAt:           older,
		LastInteractionTime: &older,
		Phase:               "idle",
		Owner:               &owner,
	}
	if err := SaveSessionState(context.Background(), owned); err != nil {
		t.Fatalf("SaveSessionState: %v", err)
	}

	got := ResolveCallerSession(context.Background())
	if got.SessionID != "ancestry-owned" {
		t.Errorf("SessionID = %q, want %q (our nearest-ancestor owner)", got.SessionID, "ancestry-owned")
	}
	if got.Resolution != ResolutionAncestry {
		t.Errorf("Resolution = %q, want %q", got.Resolution, ResolutionAncestry)
	}
	if !got.Resolution.IsCaller() {
		t.Error("IsCaller() = false for the ancestry tier")
	}
}

// The environment tier outranks ancestry: a vendor's deliberate statement
// about the process it spawned beats an inference from the process tree, which
// is unavailable on Windows and depends on an owner having been recorded.
func TestResolveCallerSession_EnvOutranksAncestry(t *testing.T) {
	clearCallerSessionEnv(t)
	callerSessionRepo(t)

	ancestry, ok := proclive.CurrentAncestry()
	if !ok {
		t.Skip("platform cannot introspect processes; the ancestry tier is unavailable here by design")
	}
	chain := ancestry.Chain()
	if len(chain) == 0 {
		t.Skip("no ancestors visible; nothing to match against")
	}
	owner := chain[0]

	now := time.Now()
	ancestryOwned := &SessionState{
		SessionID:           "ancestry-owned",
		BaseCommit:          "abc1234",
		WorktreePath:        "/some/other/worktree",
		StartedAt:           now,
		LastInteractionTime: &now,
		Phase:               "idle",
		Owner:               &owner,
	}
	if err := SaveSessionState(context.Background(), ancestryOwned); err != nil {
		t.Fatalf("SaveSessionState: %v", err)
	}
	saveState(t, "env-named", "/a/third/worktree", now.Add(-2*time.Hour))
	t.Setenv("CODEX_SESSION_ID", "env-named")

	got := ResolveCallerSession(context.Background())
	if got.SessionID != "env-named" || got.Resolution != ResolutionCallerEnv {
		t.Errorf("ResolveCallerSession() = %+v, want env-named via caller-env", got)
	}
}

